INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SYMBOLS_HM', 'MATH.G7.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HM', 'skill', 'essential', 'The groups of three depend on the place of each digit.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
