INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HM.M_COUNT_FROM_LEFT', 'MATH.G7.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HM', 'Counts the places from the left end of the number.', '{"question":"In 407,530,918 which place is the digit 5 in?","wrong_answer":"thousands","correct_answer":"hundred thousands"}'::jsonb, 'Reads the digits left to right like words and numbers the places that way.', 'The answer thousands as a wrong option, with a reason that names the idea.', 'Put the number in a place value chart and start counting from the ones on the right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HM.M_PLACE_SKIPPED_GROUP', 'MATH.G7.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HM', 'Loses a place when a group of three has zeros, or names the ten millions place as millions.', '{"question":"In 305,000,200 what is the place of the 3?","wrong_answer":"millions","correct_answer":"hundred millions"}'::jsonb, 'Reads the numbers in groups but forgets that each group has three places.', 'The answer millions as a wrong option, with a reason that names the idea.', 'Write the number under a chart with the headings Hundreds, Tens, Ones for each group.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HM.M_ZERO_NOT_A_PLACE', 'MATH.G7.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HM', 'Ignores a zero when counting places, so the digits after it move up one place.', '{"question":"In 70,408,003 which digit is in the millions place?","wrong_answer":"4","correct_answer":"0"}'::jsonb, 'Thinks a zero is empty space rather than a digit that holds a place.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'Colour each zero. Say: a zero is a digit that says there is nothing in that place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HM.M_DIGIT_FOR_TOTAL', 'MATH.G7.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HM', 'Gives the digit itself when asked for its total value.', '{"question":"What is the total value of 7 in 47,300,000?","wrong_answer":"7","correct_answer":"7,000,000"}'::jsonb, 'Confuses total value (digit times the place) with the digit.', 'The answer 7 as a wrong option, with a reason that names the idea.', 'Ask: if I had 7 notes of one million shillings, how much money? Write 7 x 1,000,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HM.M_ZEROS_MISCOUNTED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HM', 'Writes too many or too few zeros after the digit.', '{"question":"What is the total value of the 3 in 83,402,115?","wrong_answer":"3,000,000","correct_answer":"3,000"}'::jsonb, 'Counts the digit as the place name instead of counting the zeros after it.', 'The answer 3,000,000 as a wrong option, with a reason that names the idea.', 'The zeros are the places to the right of the digit. Count them off under the digits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HM.M_ONE_DIGIT_ONLY_VALUED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HM', 'Works out the total value of one digit and takes the other digit as it is.', '{"question":"Add the total values of the 2 and the 5 in 25,000,000.","wrong_answer":"20,000,000 + 5","correct_answer":"25,000,000"}'::jsonb, 'Applies place value to one digit and forgets the other needs it too.', 'The answer 20,000,000 + 5 as a wrong option, with a reason that names the idea.', 'Make a two-row table: digit, place, total value. Fill every row before adding.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SYMBOLS_HM.M_JOIN_PARTS_AS_WRITTEN', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SYMBOLS_HM', 'Joins the parts as they are said, with no place holder zeros.', '{"question":"Write 45 million, 12 thousand and 7 in figures.","wrong_answer":"45,127","correct_answer":"45,012,007"}'::jsonb, 'Sticks 45, 12 and 7 together as numbers rather than giving each group three places.', 'The answer 45,127 as a wrong option, with a reason that names the idea.', 'Draw three boxes for each group (millions, thousands, ones) and fill each with its digits and leading zeros.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SYMBOLS_HM.M_GROUP_SHIFTED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SYMBOLS_HM', 'Puts a group in the wrong place, for example thousands written in the hundreds group.', '{"question":"Write 8 million and 450 thousand in figures.","wrong_answer":"8,000,450","correct_answer":"8,450,000"}'::jsonb, 'Writes the thousands figure after the zeros of the thousands group.', 'The answer 8,000,450 as a wrong option, with a reason that names the idea.', 'Say the name of the group when you write it: 450 thousand goes in the thousands group.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SYMBOLS_HM.M_COMMA_PLACED_BY_FOUR', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SYMBOLS_HM', 'Puts a comma or space after every four digits, or reads the number in wrong groups.', '{"question":"Write 3456789012 with commas.","wrong_answer":"3456,7890,12","correct_answer":"3,456,789,012"}'::jsonb, 'Counts the digits from the left in lumps that do not match the places.', 'The answer 3456,7890,12 as a wrong option, with a reason that names the idea.', 'Start at the right and count three digits, then a comma, and so on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.WORDS_FROM_FIGURES.M_LEADING_ZERO_MISREAD', 'MATH.G7.NUMBER.WHOLE_NUMBERS.WORDS_FROM_FIGURES', 'Reads a group that starts with zero (050) as if it were a full three-digit number.', '{"question":"Write 2,050,300 in words.","wrong_answer":"two million five hundred thousand three hundred","correct_answer":"two million fifty thousand three hundred"}'::jsonb, 'Reads the digits left to right but does not match them to the group names.', 'The answer two million five hundred thousand three hundred as a wrong option, with a reason that names the idea.', 'Say each group of three with its name: 2 million, 050 thousand, 300.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.WORDS_FROM_FIGURES.M_TENS_AND_UNITS_SWAPPED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.WORDS_FROM_FIGURES', 'Swaps the tens and ones when writing the words, such as fifty-seven for seventy-five.', '{"question":"Write 1,075 in words.","wrong_answer":"one thousand and fifty-seven","correct_answer":"one thousand and seventy-five"}'::jsonb, 'Hears seventy and seventeen the same, or reads the last two digits in reverse.', 'The answer one thousand and fifty-seven as a wrong option, with a reason that names the idea.', 'Point to each digit: the left digit is tens (seven tens is seventy), the right digit is ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.WORDS_FROM_FIGURES.M_HUNDRED_DROPPED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.WORDS_FROM_FIGURES', 'Leaves out the word hundred in a group, or writes thousand for hundred.', '{"question":"Write 3,400,000 in words.","wrong_answer":"three million four thousand","correct_answer":"three million four hundred thousand"}'::jsonb, 'Hears "four" and "four hundred" as the same group.', 'The answer three million four thousand as a wrong option, with a reason that names the idea.', 'The 4 is in the hundred thousands place, so say hundred before thousand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.FIGURES_FROM_WORDS.M_GROUP_ZEROS_MISSING', 'MATH.G7.NUMBER.WHOLE_NUMBERS.FIGURES_FROM_WORDS', 'Writes the words as numbers side by side without zeros: three million and forty-five gives 345.', '{"question":"Write \"three million and forty-five\" in figures.","wrong_answer":"345","correct_answer":"3,000,045"}'::jsonb, 'Writes the numbers in the order said instead of in place value groups.', 'The answer 345 as a wrong option, with a reason that names the idea.', 'Draw the three groups and put 3 in millions, nothing in thousands (000) and 045 in ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.FIGURES_FROM_WORDS.M_THOUSAND_ONE_ZERO_SHORT', 'MATH.G7.NUMBER.WHOLE_NUMBERS.FIGURES_FROM_WORDS', 'Writes one zero too few or too many after the thousands number.', '{"question":"Write \"two hundred and fifty-seven thousand and seventy-five\" in figures.","wrong_answer":"257,750","correct_answer":"257,075"}'::jsonb, 'Forgets that a thousand group has three digits, so seventy-five becomes 750 or 75.', 'The answer 257,750 as a wrong option, with a reason that names the idea.', 'Seventy-five is only two digits, so it needs a zero in front to fill the hundreds place: 075.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.FIGURES_FROM_WORDS.M_TEEN_FOR_TY', 'MATH.G7.NUMBER.WHOLE_NUMBERS.FIGURES_FROM_WORDS', 'Writes a teen (such as 13) for a ty number (30), because they sound alike.', '{"question":"Write \"thirty thousand\" in figures.","wrong_answer":"13,000","correct_answer":"30,000"}'::jsonb, 'Mixes thirteen and thirty when listening.', 'The answer 13,000 as a wrong option, with a reason that names the idea.', 'Thirteen ends in teen (one ten and three); thirty means three tens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_TO_PLACE.M_ROUND_WRONG_DIGIT_CHECKED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_TO_PLACE', 'Looks at the digit in the place being rounded to instead of the digit after it.', '{"question":"Round 265,320,847 to the nearest hundred million.","wrong_answer":"200,000,000","correct_answer":"300,000,000"}'::jsonb, 'Thinks the digit being rounded decides, not the digit to its right.', 'The answer 200,000,000 as a wrong option, with a reason that names the idea.', 'Underline the place, then draw an arrow to the digit on its right: that one decides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_TO_PLACE.M_ROUND_DIRECTION_FIXED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_TO_PLACE', 'Always rounds the same way (usually down, by dropping digits) without looking at the next digit.', '{"question":"Round 18,294,211 to the nearest ten million.","wrong_answer":"10,000,000","correct_answer":"20,000,000"}'::jsonb, 'Thinks rounding means cutting off the end of the number.', 'The answer 10,000,000 as a wrong option, with a reason that names the idea.', 'Put the number on a number line between the two multiples and see which is nearer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_TO_PLACE.M_ZEROS_NOT_WRITTEN', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_TO_PLACE', 'Gives only the rounded digit, or replaces the later digits with nothing instead of zeros.', '{"question":"Round 265,320,847 to the nearest hundred million.","wrong_answer":"3","correct_answer":"300,000,000"}'::jsonb, 'Forgets that the rounded number must still be the same size as the original.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'The rounded number must keep every place. Fill the empty places with zeros.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_TO_PLACE.M_ROUND_TO_WRONG_PLACE', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_TO_PLACE', 'Rounds to a nearby place (for example ten million) when asked for the nearest hundred million.', '{"question":"Round 265,320,847 to the nearest hundred million.","wrong_answer":"270,000,000","correct_answer":"300,000,000"}'::jsonb, 'Does not name the place before rounding, so rounds to the one that looks easy.', 'The answer 270,000,000 as a wrong option, with a reason that names the idea.', 'Say the place aloud before you start and underline its digit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_IN_CONTEXT.M_NINE_CARRY_MISSED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_IN_CONTEXT', 'Rounds up a 9 and leaves the digit in front unchanged, so no carry.', '{"question":"Round 1,999,500 to the nearest thousand.","wrong_answer":"1,999,000","correct_answer":"2,000,000"}'::jsonb, 'Treats each digit separately and does not carry.', 'The answer 1,999,000 as a wrong option, with a reason that names the idea.', 'Rounding up means adding one place value: 1,999,000 + 1,000 = 2,000,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_IN_CONTEXT.M_ROUNDED_IS_EXACT', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_IN_CONTEXT', 'Believes a rounded number is the exact one.', '{"question":"A report says about 270,000,000 lines. Are there exactly 270,000,000?","wrong_answer":"Yes","correct_answer":"No, it is only a close estimate"}'::jsonb, 'Does not see rounding as approximating.', 'The answer Yes as a wrong option, with a reason that names the idea.', 'Ask: could the real number be 265,320,847 and still be called 270 million?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_IN_CONTEXT.M_NO_ROUNDING_FOR_MONEY', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_IN_CONTEXT', 'Says money amounts cannot be rounded.', '{"question":"Can a county budget of sh 18,294,211 be given to the nearest million?","wrong_answer":"No, money must be exact","correct_answer":"Yes: sh 18,000,000 for a report"}'::jsonb, 'Thinks money always needs to be exact.', 'The answer No, money must be exact as a wrong option, with a reason that names the idea.', 'Show a newspaper line that says "about sh 18 million". Exact amounts are for accounts, round ones for reports.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.EVEN_ODD.M_EVEN_BY_FIRST_DIGIT', 'MATH.G7.NUMBER.WHOLE_NUMBERS.EVEN_ODD', 'Uses the first digit of the number to decide if it is even or odd.', '{"question":"Is 2,357 even or odd?","wrong_answer":"even (it starts with 2)","correct_answer":"odd"}'::jsonb, 'Looks at the front of the number instead of the last digit.', 'The answer even (it starts with 2) as a wrong option, with a reason that names the idea.', 'Only the ones digit tells: 2,357 ends in 7, so one is left over when you share into twos.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.EVEN_ODD.M_ZERO_NOT_EVEN', 'MATH.G7.NUMBER.WHOLE_NUMBERS.EVEN_ODD', 'Says zero is neither even nor odd, or that odd + odd is odd.', '{"question":"Is 0 even or odd?","wrong_answer":"neither","correct_answer":"even"}'::jsonb, 'Zero does not feel like a number to count with.', 'The answer neither as a wrong option, with a reason that names the idea.', 'Zero can be shared into two equal groups of zero, and it sits between 1 and -1 in the pattern odd, even, odd.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.PRIME_NUMBERS.M_ODD_MEANS_PRIME', 'MATH.G7.NUMBER.WHOLE_NUMBERS.PRIME_NUMBERS', 'Believes every odd number is prime.', '{"question":"Is 9 prime?","wrong_answer":"Yes, it is odd","correct_answer":"No, 3 x 3 = 9"}'::jsonb, 'Mixes the idea that all primes except 2 are odd with the reverse.', 'The answer Yes, it is odd as a wrong option, with a reason that names the idea.', 'Try dividing by 3, 5 and 7: 9, 15, 21 and 27 are odd but composite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.PRIME_NUMBERS.M_ONE_IS_PRIME', 'MATH.G7.NUMBER.WHOLE_NUMBERS.PRIME_NUMBERS', 'Counts 1 as a prime number.', '{"question":"Is 1 a prime number?","wrong_answer":"Yes","correct_answer":"No, it has only one factor"}'::jsonb, 'Remembers that primes can be divided only by 1 and themselves, and 1 fits that.', 'The answer Yes as a wrong option, with a reason that names the idea.', 'A prime has exactly two different factors. 1 has just one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.PRIME_NUMBERS.M_TWO_NOT_PRIME', 'MATH.G7.NUMBER.WHOLE_NUMBERS.PRIME_NUMBERS', 'Says 2 is not prime because it is even.', '{"question":"Is 2 prime?","wrong_answer":"No, it is even","correct_answer":"Yes"}'::jsonb, 'Thinks all even numbers are composite.', 'The answer No, it is even as a wrong option, with a reason that names the idea.', 'List the factors of 2: 1 and 2 only. It is the only even prime.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ADD_SUB_LARGE.M_SMALLER_FROM_LARGER', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ADD_SUB_LARGE', 'In subtraction takes the smaller digit from the larger in each column.', '{"question":"Work out 300,400,200 - 123,456,789.","wrong_answer":"223,056,589","correct_answer":"176,943,411"}'::jsonb, 'Avoids regrouping by reversing the digits that are in the wrong order.', 'The answer 223,056,589 as a wrong option, with a reason that names the idea.', 'Show that each column must be top minus bottom; when the top is smaller, regroup from the next column.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ADD_SUB_LARGE.M_ZERO_REGROUP_BROKEN', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ADD_SUB_LARGE', 'Regroups across a zero but leaves the zero as it was, so the number grows by 10.', '{"question":"Work out 5,000,000 - 1,234,567.","wrong_answer":"3,876,543","correct_answer":"3,765,433"}'::jsonb, 'Takes 1 from the next digit only once and does not make the zero a nine.', 'The answer 3,876,543 as a wrong option, with a reason that names the idea.', 'Break the zeros: 5,000,000 = 4,999,999 + 1. Show the chain of nines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ADD_SUB_LARGE.M_COLUMN_MISALIGNED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ADD_SUB_LARGE', 'Adds or subtracts digits that are not in the same place because the numbers are not lined up from the right.', '{"question":"Add 12,500,000 and 750,000.","wrong_answer":"20,000,000","correct_answer":"13,250,000"}'::jsonb, 'Lines up numbers from the left.', 'The answer 20,000,000 as a wrong option, with a reason that names the idea.', 'Always line up the ones. Use squared paper or a place value chart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.MULT_LARGE.M_PLACE_HOLDER_ZERO_MISSING', 'MATH.G7.NUMBER.WHOLE_NUMBERS.MULT_LARGE', 'Leaves out the zero place holder in the second or third row of long multiplication.', '{"question":"Work out 235 x 124.","wrong_answer":"1,645","correct_answer":"29,140"}'::jsonb, 'Writes the second row directly under the first.', 'The answer 1,645 as a wrong option, with a reason that names the idea.', 'The second row is for tens, so it starts under the tens column. Put a zero under the ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.MULT_LARGE.M_ZEROS_LOST_BY_100', 'MATH.G7.NUMBER.WHOLE_NUMBERS.MULT_LARGE', 'Multiplies by 100 by adding only one zero, or by 1,000 by adding two zeros.', '{"question":"Work out 4,500 x 1,000.","wrong_answer":"450,000","correct_answer":"4,500,000"}'::jsonb, 'Counts the zeros of the multiplier but loses those already in the number.', 'The answer 450,000 as a wrong option, with a reason that names the idea.', 'Shift every digit three places to the left, then fill the gaps with zeros.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.MULT_LARGE.M_ONLY_ONES_DIGIT', 'MATH.G7.NUMBER.WHOLE_NUMBERS.MULT_LARGE', 'Multiplies by the ones digit of the multiplier only and ignores the tens and hundreds digits.', '{"question":"Work out 235 x 124.","wrong_answer":"940","correct_answer":"29,140"}'::jsonb, 'Treats the multiplier as the last digit only.', 'The answer 940 as a wrong option, with a reason that names the idea.', 'Split 124 into 100 + 20 + 4 and multiply by each part, then add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.DIV_LARGE.M_ZERO_IN_QUOTIENT_DROPPED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.DIV_LARGE', 'Leaves out a zero in the quotient when the next digit is too small to divide.', '{"question":"Work out 84,036 / 4.","wrong_answer":"2,109","correct_answer":"21,009"}'::jsonb, 'Brings down the next digit but forgets to write 0 when the divisor does not go in.', 'The answer 2,109 as a wrong option, with a reason that names the idea.', 'After bringing down each digit, write a digit above it, even 0.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.DIV_LARGE.M_REMAINDER_IGNORED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.DIV_LARGE', 'Gives only the quotient when the question needs the remainder, or rounds the remainder away.', '{"question":"290 pupils go in buses of 45. How many buses are needed?","wrong_answer":"6","correct_answer":"7"}'::jsonb, 'Thinks the remainder does not matter.', 'The answer 6 as a wrong option, with a reason that names the idea.', 'Draw the buses: 6 are full and 20 pupils are left, so one more is needed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.DIV_LARGE.M_DIVIDE_SMALL_BY_LARGE', 'MATH.G7.NUMBER.WHOLE_NUMBERS.DIV_LARGE', 'Divides the smaller number by the larger when setting up the division.', '{"question":"A rope 300 m long is cut into pieces of 12 m. How many pieces?","wrong_answer":"0.04 (12 divided by 300)","correct_answer":"25"}'::jsonb, 'Does not see which number is being shared.', 'The answer 0.04 (12 divided by 300) as a wrong option, with a reason that names the idea.', 'Ask: what are we sharing? That number goes inside the division bracket.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ORDER_OF_OPERATIONS.M_LEFT_TO_RIGHT_ONLY', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ORDER_OF_OPERATIONS', 'Works every operation from left to right whatever it is.', '{"question":"Work out 8 + 4 x 5.","wrong_answer":"60","correct_answer":"28"}'::jsonb, 'Reads like a sentence and does not know that multiplication comes first.', 'The answer 60 as a wrong option, with a reason that names the idea.', 'Picture 8 shillings and 4 coins of 5 shillings: that is 8 + 20.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ORDER_OF_OPERATIONS.M_BRACKETS_IGNORED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ORDER_OF_OPERATIONS', 'Ignores the brackets and applies the usual order.', '{"question":"Work out (8 + 4) x 5.","wrong_answer":"28","correct_answer":"60"}'::jsonb, 'Does not see that brackets mean work this part first.', 'The answer 28 as a wrong option, with a reason that names the idea.', 'Replace the bracket with its value first: (8 + 4) becomes 12.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ORDER_OF_OPERATIONS.M_ADD_BEFORE_SUBTRACT', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ORDER_OF_OPERATIONS', 'Always adds before subtracting, even when subtraction comes first from the left.', '{"question":"Work out 20 - 5 + 3.","wrong_answer":"12","correct_answer":"18"}'::jsonb, 'Has learnt that addition beats subtraction, like multiplication beats addition.', 'The answer 12 as a wrong option, with a reason that names the idea.', 'Addition and subtraction are equal rank: go left to right. 20 - 5 = 15, then + 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ORDER_OF_OPERATIONS.M_MULT_BEFORE_DIVIDE', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ORDER_OF_OPERATIONS', 'Always does multiplication before division even when the division comes first.', '{"question":"Work out 24 / 4 x 3.","wrong_answer":"2","correct_answer":"18"}'::jsonb, 'Has learnt a rule that multiplication always goes first.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Division and multiplication are equal rank: left to right. 24 / 4 = 6, then x 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.OPERATIONS_IN_CONTEXT.M_ONE_STEP_STOPPED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.OPERATIONS_IN_CONTEXT', 'Does the first operation in a two-step story and stops.', '{"question":"A matatu carries 30 passengers at sh 100 each. The driver pays sh 800 fuel and sh 200 parking. What is left?","wrong_answer":"3,000","correct_answer":"2,000"}'::jsonb, 'Takes the first answer as the end of the story.', 'The answer 3,000 as a wrong option, with a reason that names the idea.', 'Underline every question phrase in the story and cross them out as each is answered.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.OPERATIONS_IN_CONTEXT.M_ADDED_NOT_TAKEN_AWAY', 'MATH.G7.NUMBER.WHOLE_NUMBERS.OPERATIONS_IN_CONTEXT', 'Adds an amount that is paid out or given away instead of taking it away.', '{"question":"Takings sh 3,000, costs sh 1,000. How much is left?","wrong_answer":"4,000","correct_answer":"2,000"}'::jsonb, 'Sees two money amounts and adds them.', 'The answer 4,000 as a wrong option, with a reason that names the idea.', 'Ask: does the driver get money or pay money? Paying means it leaves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.OPERATIONS_IN_CONTEXT.M_TOTAL_GIVEN_AS_SHARE', 'MATH.G7.NUMBER.WHOLE_NUMBERS.OPERATIONS_IN_CONTEXT', 'Gives the amount left in total as the amount each person gets, without dividing.', '{"question":"Barasa has 45 mangoes, gives away 15, then shares the rest among 5 families.","wrong_answer":"30 each","correct_answer":"6 each"}'::jsonb, 'Gives the amount left as the amount each gets.', 'The answer 30 each as a wrong option, with a reason that names the idea.', 'Check: 30 is the amount left in total. Divide it by the 5 families.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_EXTEND_RULE.M_ADD_NOT_MULTIPLY', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_EXTEND_RULE', 'Adds a constant when the terms are growing by multiplying.', '{"question":"What comes after 2, 6, 18, 54?","wrong_answer":"90","correct_answer":"162"}'::jsonb, 'Sees the first gap (4) and keeps adding it.', 'The answer 90 as a wrong option, with a reason that names the idea.', 'Check the gaps: 4, 12, 36 are not equal. Check the ratios: all x 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_EXTEND_RULE.M_FIRST_GAP_ONLY', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_EXTEND_RULE', 'Finds the rule from the first two terms and does not test it on the others.', '{"question":"17, 24, 33, 38, 45, 52: which term does not fit?","wrong_answer":"38","correct_answer":"33"}'::jsonb, 'Trusts the first gap and calls anything else wrong.', 'The answer 38 as a wrong option, with a reason that names the idea.', 'Find all the gaps. The gap that appears most often is the rule.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_EXTEND_RULE.M_DECREASING_SIGN', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_EXTEND_RULE', 'Adds instead of subtracting when the terms get smaller.', '{"question":"What comes after 40, 34, 28, 22?","wrong_answer":"28","correct_answer":"16"}'::jsonb, 'Goes through the sequence looking at the size of the gap and forgets the direction.', 'The answer 28 as a wrong option, with a reason that names the idea.', 'The terms get smaller, so the rule is take away 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_NTH_TERM.M_COUNT_TERMS_NOT_STEPS', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_NTH_TERM', 'Multiplies the difference by the position instead of by the number of steps from the first term.', '{"question":"21, 24, 27, 30. What is the 12th term?","wrong_answer":"57","correct_answer":"54"}'::jsonb, 'Thinks the first term needs a step too.', 'The answer 57 as a wrong option, with a reason that names the idea.', 'From the 1st to the 12th term there are only 11 steps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_NTH_TERM.M_FIRST_TERM_LEFT_OUT', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_NTH_TERM', 'Gives the number of steps times the difference but does not add the first term.', '{"question":"21, 24, 27, 30. What is the 12th term?","wrong_answer":"33","correct_answer":"54"}'::jsonb, 'Forgets that the sequence started at 21, not 0.', 'The answer 33 as a wrong option, with a reason that names the idea.', 'Add where you started: 21 + 11 x 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_NTH_TERM.M_NEXT_TERM_NOT_FAR', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_NTH_TERM', 'Gives the next term when asked for a term far along.', '{"question":"5, 9, 13, 17. What is the 10th term?","wrong_answer":"21","correct_answer":"41"}'::jsonb, 'Tries to continue term by term and stops early.', 'The answer 21 as a wrong option, with a reason that names the idea.', 'Use first term + steps x difference to jump straight to the 12th.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_CREATE_RULE.M_ONLY_ADDING_USED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_CREATE_RULE', 'Uses only the adding part of a two-part rule.', '{"question":"Rule: multiply by 3, then add 3. First term 1. What is the 2nd term?","wrong_answer":"4","correct_answer":"6"}'::jsonb, 'Does the last operation named and forgets the first.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'Write the rule as two boxes: x 3, then + 3. Put each term through both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_CREATE_RULE.M_ONLY_MULTIPLYING_USED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_CREATE_RULE', 'Uses only the multiplying part of a two-part rule.', '{"question":"Rule: multiply by 3, then add 3. First term 1. What is the 4th term?","wrong_answer":"27","correct_answer":"66"}'::jsonb, 'Does the first operation named and forgets the second.', 'The answer 27 as a wrong option, with a reason that names the idea.', 'Write the rule as two boxes. Each step goes through both boxes: x 3, then + 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_CREATE_RULE.M_RULE_NOT_KEPT', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_CREATE_RULE', 'Writes terms that do not all follow the rule.', '{"question":"Rule: add 5 to 2. Write four terms.","wrong_answer":"2, 7, 13, 18","correct_answer":"2, 7, 12, 17"}'::jsonb, 'Drifts to a different gap partway.', 'The answer 2, 7, 13, 18 as a wrong option, with a reason that names the idea.', 'Check each pair of neighbours: the gap must be the same every time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HM.M_PLACE_ONE_TOO_HIGH', 'MATH.G7.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HM', 'Counts the place one too high, so the total value has one zero too many.', '{"question":"What is the total value of the 4 in 4,215,000?","wrong_answer":"40,000,000","correct_answer":"4,000,000"}'::jsonb, 'Counts the ones place as the first place instead of the place to the right of it.', 'The answer 40,000,000 as a wrong option, with a reason that names the idea.', 'Count the zeros: the digit that is the first in a 7-digit number has six zeros after it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.WORDS_FROM_FIGURES.M_DIGIT_MOVED_ACROSS_GROUPS', 'MATH.G7.NUMBER.WHOLE_NUMBERS.WORDS_FROM_FIGURES', 'Moves a digit into the neighbouring group when reading, so the words describe a different number.', '{"question":"Write 6,350,128 in words.","wrong_answer":"six million three hundred and five thousand one hundred and twenty-eight","correct_answer":"six million three hundred and fifty thousand one hundred and twenty-eight"}'::jsonb, 'Reads the digits one after the other without keeping to the groups of three.', 'The answer six million three hundred and five thousand one hundred and twenty-eight as a wrong option, with a reason that names the idea.', 'Split the number into groups with commas first, then read each group on its own.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.WORDS_FROM_FIGURES.M_ORDER_WITHIN_GROUP_SWAPPED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.WORDS_FROM_FIGURES', 'Reads two digits of one group in the wrong order.', '{"question":"Write 1,807,402 in words.","wrong_answer":"one million eight hundred and seventy thousand four hundred and two","correct_answer":"one million eight hundred and seven thousand four hundred and two"}'::jsonb, 'Skips over a zero in the middle of a group and reads the next digit as tens.', 'The answer one million eight hundred and seventy thousand four hundred and two as a wrong option, with a reason that names the idea.', 'In 807 the 0 means no tens, so the group reads eight hundred and seven.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_TO_PLACE.M_ROUND_LAST_DIGIT_ONLY', 'MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_TO_PLACE', 'Looks at the last digit of the whole number, not the digit just after the place being rounded to.', '{"question":"Round 18,694,215 to the nearest million.","wrong_answer":"18,000,000","correct_answer":"19,000,000"}'::jsonb, 'Believes the last digit of a number decides how it rounds.', 'The answer 18,000,000 as a wrong option, with a reason that names the idea.', 'Underline the millions digit, then the digit right after it: 6 decides, not the 5 at the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.PRIME_NUMBERS.M_PRIME_COMPOSITE_CONFUSED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.PRIME_NUMBERS', 'Mixes up prime and composite and picks the composite numbers.', '{"question":"Which of 7, 9, 12 is prime?","wrong_answer":"12","correct_answer":"7"}'::jsonb, 'Cannot hold apart the two words and what each means.', 'The answer 12 as a wrong option, with a reason that names the idea.', 'A prime is on its own: only 1 and itself divide it. A composite is built from smaller factors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.PRIME_NUMBERS.M_ONLY_SMALL_DIVISORS_TESTED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.PRIME_NUMBERS', 'Tests only 2 and 3 as divisors, so calls 25 and 35 prime.', '{"question":"Is 35 prime?","wrong_answer":"Yes, 2 and 3 do not divide it","correct_answer":"No, 5 x 7 = 35"}'::jsonb, 'Stops testing after the first two divisors.', 'The answer Yes, 2 and 3 do not divide it as a wrong option, with a reason that names the idea.', 'Test 2, 3, 5 and 7 in order. A number up to 100 that none of these divide is prime.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.OPERATIONS_IN_CONTEXT.M_LAST_COST_LEFT_OUT', 'MATH.G7.NUMBER.WHOLE_NUMBERS.OPERATIONS_IN_CONTEXT', 'Takes away the first cost in the story but not the second.', '{"question":"Fares sh 3,000, fuel sh 800 and parking sh 200. How much is left?","wrong_answer":"sh 2,200","correct_answer":"sh 2,000"}'::jsonb, 'Stops reading the story before the last sentence.', 'The answer sh 2,200 as a wrong option, with a reason that names the idea.', 'Underline every money amount in the story and tick each one off when it is used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.OPERATIONS_IN_CONTEXT.M_SHARE_BY_MULTIPLYING', 'MATH.G7.NUMBER.WHOLE_NUMBERS.OPERATIONS_IN_CONTEXT', 'Multiplies where the story says share equally.', '{"question":"30 mangoes are shared equally among 5 families. How many does each get?","wrong_answer":"150","correct_answer":"6"}'::jsonb, 'Sees two numbers and multiplies them.', 'The answer 150 as a wrong option, with a reason that names the idea.', 'Draw 5 baskets and deal the mangoes out one at a time: sharing needs division.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_EXTEND_RULE.M_NEIGHBOUR_BLAMED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_EXTEND_RULE', 'Blames the term next to the wrong one because the gap beside it also looks different.', '{"question":"17, 24, 33, 38, 45, 52: which term does not fit the pattern of adding 7?","wrong_answer":"38","correct_answer":"33"}'::jsonb, 'Sees two odd gaps (24 to 33 and 33 to 38) and picks the second term of the second gap.', 'The answer 38 as a wrong option, with a reason that names the idea.', 'Work out what each term should be (17, 24, 31, 38, 45, 52) and see which one is different.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_EXTEND_RULE.M_GIVES_CORRECT_TERM', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_EXTEND_RULE', 'Gives the term that should be there instead of the wrong term that was written.', '{"question":"17, 24, 33, 38, 45, 52 goes up by 7 each time but one term is wrong. Which term is wrong?","wrong_answer":"31","correct_answer":"33"}'::jsonb, 'Answers a different question: what the term should be.', 'The answer 31 as a wrong option, with a reason that names the idea.', 'Read the question again: which term that is written down does not fit?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_NTH_TERM.M_MULTIPLIES_FIRST_TERM', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_NTH_TERM', 'Multiplies the first term by the position, ignoring the rule.', '{"question":"A row of hexagons starts with 6 sticks and each new one adds 5. How many sticks in 4 hexagons?","wrong_answer":"24","correct_answer":"21"}'::jsonb, 'Treats every shape as if it needed all its own sticks.', 'The answer 24 as a wrong option, with a reason that names the idea.', 'Draw the first two shapes and count: the second shape shares a side, so it adds only 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_NTH_TERM.M_DIFFERENCE_IGNORED', 'MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_NTH_TERM', 'Adds 1 for each step instead of the difference.', '{"question":"A row starts with 6 sticks and each new shape adds 5. How many sticks in 4 shapes?","wrong_answer":"9","correct_answer":"21"}'::jsonb, 'Counts the number of shapes instead of the sticks they add.', 'The answer 9 as a wrong option, with a reason that names the idea.', 'Each new shape adds 5 sticks, not 1. Write the rule as: add 5 each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.DIV_BY_2_4_8_5_10.M_LAST_DIGIT_FOR_4_8', 'MATH.G7.NUMBER.FACTORS.DIV_BY_2_4_8_5_10', 'Tests divisibility by 4 or 8 from the last digit only.', '{"question":"Is 3,614 divisible by 4?","wrong_answer":"Yes, it ends in 4 (even)","correct_answer":"No: 14 is not divisible by 4"}'::jsonb, 'Extends the rule for 2 to 4 and 8.', 'The answer Yes, it ends in 4 (even) as a wrong option, with a reason that names the idea.', 'For 4 look at the last two digits, for 8 the last three.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.DIV_BY_2_4_8_5_10.M_EVEN_MEANS_DIVISIBLE_BY_4', 'MATH.G7.NUMBER.FACTORS.DIV_BY_2_4_8_5_10', 'Believes every even number is divisible by 4.', '{"question":"Is 4,126 divisible by 4?","wrong_answer":"Yes, it is even","correct_answer":"No: 26 is not divisible by 4"}'::jsonb, 'Mixes up divisible by 2 with divisible by 4.', 'The answer Yes, it is even as a wrong option, with a reason that names the idea.', 'Halve it, then halve again: if the first half is odd it fails.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.DIV_BY_3_6_9.M_DIGIT_SUM_NOT_DIVIDED', 'MATH.G7.NUMBER.FACTORS.DIV_BY_3_6_9', 'Calls a number divisible by 3 or 9 without testing the digit sum, or accepts a sum that is not a multiple.', '{"question":"Is 8,180 divisible by 3?","wrong_answer":"Yes (digits add to 17)","correct_answer":"No: 17 is not a multiple of 3"}'::jsonb, 'Adds the digits but forgets to check if the sum is a multiple of 3.', 'The answer Yes (digits add to 17) as a wrong option, with a reason that names the idea.', 'After adding the digits, ask: is the sum in the 3 times table?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.DIV_BY_3_6_9.M_SIX_ONLY_THREE_TESTED', 'MATH.G7.NUMBER.FACTORS.DIV_BY_3_6_9', 'Tests only divisibility by 3 for 6.', '{"question":"Is 4,125 divisible by 6?","wrong_answer":"Yes, the digit sum 12 is a multiple of 3","correct_answer":"No: it is odd"}'::jsonb, 'Forgets that 6 = 2 x 3 needs both tests.', 'The answer Yes, the digit sum 12 is a multiple of 3 as a wrong option, with a reason that names the idea.', 'A number divisible by 6 must pass the test for 2 and the test for 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.DIV_BY_3_6_9.M_SIX_ONLY_EVEN_TESTED', 'MATH.G7.NUMBER.FACTORS.DIV_BY_3_6_9', 'Tests only that the number is even for 6.', '{"question":"Is 4,126 divisible by 6?","wrong_answer":"Yes, it is even","correct_answer":"No: the digit sum 13 is not a multiple of 3"}'::jsonb, 'Forgets the test for 3.', 'The answer Yes, it is even as a wrong option, with a reason that names the idea.', 'Check both: even, and the digit sum a multiple of 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.DIV_BY_3_6_9.M_DIGIT_SUM_DIVISIBLE_BY_SIX', 'MATH.G7.NUMBER.FACTORS.DIV_BY_3_6_9', 'Uses the digit sum test for 6 by asking if the digit sum is a multiple of 6.', '{"question":"Is 4,125 divisible by 6? (digits add to 12)","wrong_answer":"Yes, 12 is a multiple of 6","correct_answer":"No: it is odd"}'::jsonb, 'Copies the 3 and 9 rule to 6.', 'The answer Yes, 12 is a multiple of 6 as a wrong option, with a reason that names the idea.', 'The digit sum rule works for 3 and 9 only. For 6 use even and digit sum for 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.DIV_BY_11.M_ELEVEN_ADD_ALL_DIGITS', 'MATH.G7.NUMBER.FACTORS.DIV_BY_11', 'Adds all the digits and tests the sum for 11.', '{"question":"Is 5,445 divisible by 11?","wrong_answer":"No: 5+4+4+5 = 18, not a multiple of 11","correct_answer":"Yes: (5+4) - (4+5) = 0"}'::jsonb, 'Uses the 3 and 9 rule for 11.', 'The answer No: 5+4+4+5 = 18, not a multiple of 11 as a wrong option, with a reason that names the idea.', 'For 11 add the digits in odd places, then in even places, and subtract.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.DIV_BY_11.M_ELEVEN_ZERO_ONLY', 'MATH.G7.NUMBER.FACTORS.DIV_BY_11', 'Accepts only a difference of 0 and misses a difference of 11.', '{"question":"Is 3,718 divisible by 11?","wrong_answer":"No: the difference is 11, not 0","correct_answer":"Yes: 11 is a multiple of 11"}'::jsonb, 'Believes the difference must be exactly 0.', 'The answer No: the difference is 11, not 0 as a wrong option, with a reason that names the idea.', 'The difference can be 0, 11, 22 and so on: any multiple of 11.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.PRIME_FACTORISE.M_FACTORS_NOT_PRIME', 'MATH.G7.NUMBER.FACTORS.PRIME_FACTORISE', 'Stops with a composite factor, such as 396 = 2 x 2 x 9 x 11.', '{"question":"Write 396 as a product of prime factors.","wrong_answer":"2 x 2 x 9 x 11","correct_answer":"2 x 2 x 3 x 3 x 11"}'::jsonb, 'Stops at the first factors found.', 'The answer 2 x 2 x 9 x 11 as a wrong option, with a reason that names the idea.', 'Check each factor: if it can be split, split it again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.PRIME_FACTORISE.M_REPEATED_FACTOR_ONCE', 'MATH.G7.NUMBER.FACTORS.PRIME_FACTORISE', 'Writes a repeated prime factor only once.', '{"question":"Write 36 as a product of prime factors.","wrong_answer":"2 x 3","correct_answer":"2 x 2 x 3 x 3"}'::jsonb, 'Thinks a prime factor needs to be listed once.', 'The answer 2 x 3 as a wrong option, with a reason that names the idea.', 'Multiply your answer back: 2 x 3 is only 6, so more factors are needed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.PRIME_FACTORISE.M_SMALL_PRIMES_ENOUGH', 'MATH.G7.NUMBER.FACTORS.PRIME_FACTORISE', 'Believes a number that does not divide by 2, 3 or 5 is prime.', '{"question":"Is 143 prime?","wrong_answer":"Yes, 2, 3 and 5 do not divide it","correct_answer":"No: 143 = 11 x 13"}'::jsonb, 'Tests only the first three primes.', 'The answer Yes, 2, 3 and 5 do not divide it as a wrong option, with a reason that names the idea.', 'Keep testing primes until the square of the prime is larger than the number.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.PRIME_FACTORISE.M_PRIMES_STOP_AT_100', 'MATH.G7.NUMBER.FACTORS.PRIME_FACTORISE', 'Believes prime numbers stop at 100.', '{"question":"Is 101 prime?","wrong_answer":"No, primes stop at 100","correct_answer":"Yes: no prime divides it"}'::jsonb, 'Has only seen primes up to 100 in a table.', 'The answer No, primes stop at 100 as a wrong option, with a reason that names the idea.', 'Test 101 with 2, 3, 5 and 7: none divides it, so it is prime.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.GCD_BY_FACTORS.M_GCD_IS_LCM', 'MATH.G7.NUMBER.FACTORS.GCD_BY_FACTORS', 'Gives the LCM when asked for the GCD.', '{"question":"GCD of 63 and 81","wrong_answer":"567","correct_answer":"9"}'::jsonb, 'Mixes up common factors and common multiples.', 'The answer 567 as a wrong option, with a reason that names the idea.', 'The GCD divides both numbers, so it cannot be larger than the smaller one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.GCD_BY_FACTORS.M_GCD_DIFFERENCE', 'MATH.G7.NUMBER.FACTORS.GCD_BY_FACTORS', 'Uses the difference of the numbers as the GCD.', '{"question":"GCD of 63 and 81","wrong_answer":"18","correct_answer":"9"}'::jsonb, 'Believes the GCD is the gap between the numbers.', 'The answer 18 as a wrong option, with a reason that names the idea.', 'Check: does 18 divide 63 exactly? It does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.GCD_BY_FACTORS.M_MULTIPLE_VS_FACTOR_CONFUSED', 'MATH.G7.NUMBER.FACTORS.GCD_BY_FACTORS', 'Mixes up factor and multiple.', '{"question":"Is 120 a multiple of 6?","wrong_answer":"No: 120 is not a factor of 6","correct_answer":"Yes: 6 x 20 = 120"}'::jsonb, 'Says "not a factor" when the question is about multiples.', 'The answer No: 120 is not a factor of 6 as a wrong option, with a reason that names the idea.', 'A multiple is in the times table of the number; a factor divides into it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.LCM_BY_FACTORS.M_LCM_PRODUCT', 'MATH.G7.NUMBER.FACTORS.LCM_BY_FACTORS', 'Takes the product of the two numbers as the LCM.', '{"question":"LCM of 12 and 8","wrong_answer":"96","correct_answer":"24"}'::jsonb, 'Takes any common multiple as the least.', 'The answer 96 as a wrong option, with a reason that names the idea.', 'List multiples of 12 and 8 and find the first one in both lists.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.LCM_BY_FACTORS.M_LCM_ADD_THE_GAPS', 'MATH.G7.NUMBER.FACTORS.LCM_BY_FACTORS', 'Adds the two numbers to find the LCM.', '{"question":"LCM of 12 and 8","wrong_answer":"20","correct_answer":"24"}'::jsonb, 'Adds because the story gives two numbers.', 'The answer 20 as a wrong option, with a reason that names the idea.', 'Check: is 20 in the 12 times table?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.LCM_BY_FACTORS.M_LCM_SMALLER_THAN_NUMBERS', 'MATH.G7.NUMBER.FACTORS.LCM_BY_FACTORS', 'Believes the LCM must be smaller than the numbers.', '{"question":"LCM of 6 and 20","wrong_answer":"2","correct_answer":"60"}'::jsonb, 'Mixes the LCM with the GCD.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'A multiple is never smaller than the number itself.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.GCD_IN_CONTEXT.M_SMALLEST_QUANTITY_IS_GCD', 'MATH.G7.NUMBER.FACTORS.GCD_IN_CONTEXT', 'Gives the smallest quantity as the greatest number of groups.', '{"question":"24, 30 and 18 items. Greatest number of equal packs?","wrong_answer":"18","correct_answer":"6"}'::jsonb, 'Thinks the packs cannot be more than the smallest stock.', 'The answer 18 as a wrong option, with a reason that names the idea.', 'Check: does 18 divide 24 and 30 exactly?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.GCD_IN_CONTEXT.M_GCD_TWO_OF_THREE', 'MATH.G7.NUMBER.FACTORS.GCD_IN_CONTEXT', 'Finds the GCD of two of the three numbers only.', '{"question":"24, 36 and 30 items: the greatest number of equal packs?","wrong_answer":"12","correct_answer":"6"}'::jsonb, 'Stops after two numbers.', 'The answer 12 as a wrong option, with a reason that names the idea.', 'The third number must divide exactly too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.GCD_IN_CONTEXT.M_OTHER_QUANTITY_GIVEN', 'MATH.G7.NUMBER.FACTORS.GCD_IN_CONTEXT', 'Gives the other quantity: the number of pieces for the length, or the contents of a pack for the number of packs.', '{"question":"Ropes of 63 m and 81 m are cut into equal longest pieces. How long is each piece?","wrong_answer":"16","correct_answer":"9"}'::jsonb, 'Answers the number of pieces instead of their length.', 'The answer 16 as a wrong option, with a reason that names the idea.', 'Read the last sentence: what is the question asking for?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.LCM_IN_CONTEXT.M_LCM_ONE_GAP_ONLY', 'MATH.G7.NUMBER.FACTORS.LCM_IN_CONTEXT', 'Gives one of the gaps as the time they meet.', '{"question":"Matatus every 12 and 8 minutes: when together again?","wrong_answer":"12 minutes","correct_answer":"24 minutes"}'::jsonb, 'Looks at the first time one of them leaves.', 'The answer 12 minutes as a wrong option, with a reason that names the idea.', 'Check: does the 8 minute matatu leave at 12 minutes?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FACTORS.LCM_IN_CONTEXT.M_LCM_TWO_OF_THREE', 'MATH.G7.NUMBER.FACTORS.LCM_IN_CONTEXT', 'Finds the LCM of two of three numbers only.', '{"question":"Bells every 6, 10 and 8 minutes: when do all three ring together?","wrong_answer":"30 minutes","correct_answer":"120 minutes"}'::jsonb, 'Forgets the third bell.', 'The answer 30 minutes as a wrong option, with a reason that names the idea.', 'Check the answer in all three lists.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.COMPARE_FRACTIONS.M_BIGGER_DENOMINATOR_BIGGER', 'MATH.G7.NUMBER.FRACTIONS.COMPARE_FRACTIONS', 'Believes the fraction with the bigger denominator is the bigger fraction.', '{"question":"Which is greater: 3/8 or 3/5?","wrong_answer":"3/8","correct_answer":"3/5"}'::jsonb, 'Takes the bigger bottom number as meaning more.', 'The answer 3/8 as a wrong option, with a reason that names the idea.', 'Draw two equal bars: eighths are smaller pieces than fifths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.COMPARE_FRACTIONS.M_NUMERATOR_ONLY_COMPARED', 'MATH.G7.NUMBER.FRACTIONS.COMPARE_FRACTIONS', 'Compares the numerators only.', '{"question":"Which is greater: 2/9 or 1/2?","wrong_answer":"2/9","correct_answer":"1/2"}'::jsonb, 'Looks at the top numbers and ignores the size of the pieces.', 'The answer 2/9 as a wrong option, with a reason that names the idea.', 'Rename both with the same denominator: 4/18 and 9/18.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.COMPARE_FRACTIONS.M_ONE_PIECE_SHORT_EQUAL', 'MATH.G7.NUMBER.FRACTIONS.COMPARE_FRACTIONS', 'Says fractions that are each one piece short of a whole are equal.', '{"question":"4/5 and 5/6: which is greater?","wrong_answer":"They are equal","correct_answer":"5/6"}'::jsonb, 'Sees the same gap of one piece without seeing the pieces differ in size.', 'The answer They are equal as a wrong option, with a reason that names the idea.', 'A sixth is smaller than a fifth, so less is missing from 5/6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.ADD_UNLIKE_FRACTIONS.M_ADD_ACROSS', 'MATH.G7.NUMBER.FRACTIONS.ADD_UNLIKE_FRACTIONS', 'Adds the numerators and the denominators.', '{"question":"1/2 + 1/3","wrong_answer":"2/5","correct_answer":"5/6"}'::jsonb, 'Treats the bar like a separator between two whole numbers.', 'The answer 2/5 as a wrong option, with a reason that names the idea.', 'Shade 1/2 and 1/3 of one bar: together they are more than 1/2, not 2/5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.ADD_UNLIKE_FRACTIONS.M_RENAME_BOTTOM_ONLY', 'MATH.G7.NUMBER.FRACTIONS.ADD_UNLIKE_FRACTIONS', 'Renames the denominators but leaves the numerators unchanged.', '{"question":"1/2 + 1/3","wrong_answer":"2/6","correct_answer":"5/6"}'::jsonb, 'Remembers a common denominator but forgets the top must change too.', 'The answer 2/6 as a wrong option, with a reason that names the idea.', 'Multiply top and bottom: 1/2 = 3/6 and 1/3 = 2/6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.ADD_UNLIKE_FRACTIONS.M_CARRIED_WHOLE_DROPPED', 'MATH.G7.NUMBER.FRACTIONS.ADD_UNLIKE_FRACTIONS', 'Adds whole parts and fraction parts but loses the whole carried from the fractions.', '{"question":"2 3/4 + 1 3/4","wrong_answer":"3 1/2","correct_answer":"4 1/2"}'::jsonb, 'Writes 3/4 + 3/4 = 6/4 but forgets to change 6/4 into 1 2/4.', 'The answer 3 1/2 as a wrong option, with a reason that names the idea.', 'Change 6/4 into 1 2/4 and add that 1 to the wholes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.SUBTRACT_UNLIKE_FRACTIONS.M_SUBTRACT_ACROSS', 'MATH.G7.NUMBER.FRACTIONS.SUBTRACT_UNLIKE_FRACTIONS', 'Subtracts the numerators and the denominators.', '{"question":"3/4 - 1/3","wrong_answer":"2/1","correct_answer":"5/12"}'::jsonb, 'Treats the fraction bar like a separator between two whole numbers.', 'The answer 2/1 as a wrong option, with a reason that names the idea.', 'Rename 3/4 and 1/3 with the denominator 12 first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.SUBTRACT_UNLIKE_FRACTIONS.M_SMALLER_FROM_LARGER_FRACTION', 'MATH.G7.NUMBER.FRACTIONS.SUBTRACT_UNLIKE_FRACTIONS', 'Subtracts the smaller fraction from the larger one in each place.', '{"question":"4 1/5 - 1 3/5","wrong_answer":"3 2/5","correct_answer":"2 3/5"}'::jsonb, 'Avoids regrouping by reversing 1/5 and 3/5.', 'The answer 3 2/5 as a wrong option, with a reason that names the idea.', 'You cannot take 3/5 from 1/5. Take one whole from the 4 and turn it into 5/5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.SUBTRACT_UNLIKE_FRACTIONS.M_BORROWED_WHOLE_NOT_REDUCED', 'MATH.G7.NUMBER.FRACTIONS.SUBTRACT_UNLIKE_FRACTIONS', 'Regroups a whole into the fraction part but leaves the whole number as it was.', '{"question":"4 1/5 - 1 3/5","wrong_answer":"3 3/5","correct_answer":"2 3/5"}'::jsonb, 'Adds 5/5 to the fraction but forgets the whole became one smaller.', 'The answer 3 3/5 as a wrong option, with a reason that names the idea.', 'Write 4 1/5 as 3 6/5: the whole goes down by 1 when the fraction goes up by 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_WHOLE.M_WHOLE_MULTIPLIES_DENOMINATOR', 'MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_WHOLE', 'Multiplies the denominator by the whole number as well as the numerator.', '{"question":"3 x 2/5","wrong_answer":"6/15","correct_answer":"6/5"}'::jsonb, 'Multiplies both parts of the fraction.', 'The answer 6/15 as a wrong option, with a reason that names the idea.', 'Three groups of 2 fifths is 6 fifths: the pieces stay fifths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_WHOLE.M_ONLY_DIVIDED_BY_DENOMINATOR', 'MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_WHOLE', 'Finds a fraction of an amount by dividing by the denominator only.', '{"question":"2/5 of 30","wrong_answer":"6","correct_answer":"12"}'::jsonb, 'Does half the job: finds 1/5 and stops.', 'The answer 6 as a wrong option, with a reason that names the idea.', 'First find one fifth (6), then take 2 of them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_FRACTION.M_ADD_FRACTIONS_INSTEAD', 'MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_FRACTION', 'Adds the fractions when told to find a part of a part.', '{"question":"2/3 x 3/4","wrong_answer":"17/12","correct_answer":"1/2"}'::jsonb, 'Sees two fractions and applies the operation learnt last.', 'The answer 17/12 as a wrong option, with a reason that names the idea.', 'Shade 3/4 of a bar, then 2/3 of that shaded part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_FRACTION.M_MIXED_PARTS_MULTIPLIED_SEPARATELY', 'MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_FRACTION', 'Multiplies the whole parts and the fraction parts of mixed numbers separately.', '{"question":"2 1/2 x 3 1/2","wrong_answer":"6 1/4","correct_answer":"8 3/4"}'::jsonb, 'Treats a mixed number as two separate numbers.', 'The answer 6 1/4 as a wrong option, with a reason that names the idea.', 'Change both to improper fractions: 5/2 x 7/2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_FRACTION.M_FRACTION_OF_WRONG_WHOLE', 'MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_FRACTION', 'Takes the second fraction of the whole amount instead of of the first part.', '{"question":"36 acres, 5/6 maize, 2/5 of the maize land by the river: how many acres?","wrong_answer":"14.4 acres","correct_answer":"12 acres"}'::jsonb, 'Does not see that the second fraction belongs to the maize land only.', 'The answer 14.4 acres as a wrong option, with a reason that names the idea.', 'Find the maize land first (30 acres), then take 2/5 of that.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_FRACTION.M_STOPPED_AFTER_FIRST_FRACTION', 'MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_FRACTION', 'Finds the first part of a two-part story and stops.', '{"question":"36 acres, 5/6 maize, 2/5 of the maize land by the river: how many acres?","wrong_answer":"30 acres","correct_answer":"12 acres"}'::jsonb, 'Reads the first sentence and gives the first answer.', 'The answer 30 acres as a wrong option, with a reason that names the idea.', 'Underline the question: how many acres of maize are by the river?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.RECIPROCAL.M_NOT_FLIPPED', 'MATH.G7.NUMBER.FRACTIONS.RECIPROCAL', 'Multiplies by the fraction itself instead of its reciprocal.', '{"question":"12 divided by 2/5 using the reciprocal","wrong_answer":"4.8","correct_answer":"30"}'::jsonb, 'Forgets to turn the fraction upside down.', 'The answer 4.8 as a wrong option, with a reason that names the idea.', 'The reciprocal of 2/5 is 5/2. Check: 2/5 x 5/2 = 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.RECIPROCAL.M_ONLY_DENOMINATOR_USED', 'MATH.G7.NUMBER.FRACTIONS.RECIPROCAL', 'Uses only the denominator of the reciprocal.', '{"question":"12 x reciprocal of 2/5","wrong_answer":"60","correct_answer":"30"}'::jsonb, 'Thinks the reciprocal is the whole number 5.', 'The answer 60 as a wrong option, with a reason that names the idea.', 'The reciprocal has a top and a bottom: 5/2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.RECIPROCAL.M_ONLY_NUMERATOR_USED', 'MATH.G7.NUMBER.FRACTIONS.RECIPROCAL', 'Uses only the numerator of the fraction.', '{"question":"12 x reciprocal of 2/5","wrong_answer":"24","correct_answer":"30"}'::jsonb, 'Keeps one number and drops the other.', 'The answer 24 as a wrong option, with a reason that names the idea.', 'Multiply 12 by 5/2: use both numbers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.RECIPROCAL.M_MIXED_NUMBER_FLIPPED_BY_PARTS', 'MATH.G7.NUMBER.FRACTIONS.RECIPROCAL', 'Flips only the fraction part of a mixed number and keeps the whole.', '{"question":"Reciprocal of 2 2/3","wrong_answer":"2 3/2","correct_answer":"3/8"}'::jsonb, 'Believes the whole number part stays.', 'The answer 2 3/2 as a wrong option, with a reason that names the idea.', 'Write 2 2/3 as 8/3 first, then turn it over.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.RECIPROCAL.M_MIXED_NUMBER_HAS_NONE', 'MATH.G7.NUMBER.FRACTIONS.RECIPROCAL', 'Says a mixed number has no reciprocal.', '{"question":"Does 2 2/3 have a reciprocal?","wrong_answer":"No","correct_answer":"Yes: 3/8"}'::jsonb, 'Thinks only fractions can be flipped.', 'The answer No as a wrong option, with a reason that names the idea.', 'Every number except 0 has a reciprocal: change 2 2/3 into 8/3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.RECIPROCAL.M_RECIPROCAL_IS_NEGATIVE', 'MATH.G7.NUMBER.FRACTIONS.RECIPROCAL', 'Believes the reciprocal is the number with a minus sign.', '{"question":"Reciprocal of 3/4","wrong_answer":"-3/4","correct_answer":"4/3"}'::jsonb, 'Mixes up reciprocal with opposite.', 'The answer -3/4 as a wrong option, with a reason that names the idea.', 'A number times its reciprocal is 1: 3/4 x 4/3 = 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_FRACTION_BY_WHOLE.M_WHOLE_ADDED_TO_DENOMINATOR', 'MATH.G7.NUMBER.FRACTIONS.DIVIDE_FRACTION_BY_WHOLE', 'Adds the whole number to the denominator.', '{"question":"3/8 divided by 4","wrong_answer":"3/12","correct_answer":"3/32"}'::jsonb, 'Does not see division as making each part smaller by multiplying the denominator.', 'The answer 3/12 as a wrong option, with a reason that names the idea.', 'Share 3/8 among 4: each part is cut into 4 smaller pieces.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_FRACTION_BY_WHOLE.M_FLIPPED_THE_DIVIDEND', 'MATH.G7.NUMBER.FRACTIONS.DIVIDE_FRACTION_BY_WHOLE', 'Turns the fraction upside down instead of the number it is divided by.', '{"question":"3/8 divided by 4","wrong_answer":"32/3","correct_answer":"3/32"}'::jsonb, 'Remembers "flip" but flips the wrong number.', 'The answer 32/3 as a wrong option, with a reason that names the idea.', 'Only the divisor, 4, turns upside down: 3/8 x 1/4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_FRACTION_BY_WHOLE.M_MULTIPLIED_BY_DIVISOR', 'MATH.G7.NUMBER.FRACTIONS.DIVIDE_FRACTION_BY_WHOLE', 'Multiplies the fraction by the whole number when asked to share.', '{"question":"3/8 divided by 4","wrong_answer":"3/2","correct_answer":"3/32"}'::jsonb, 'Does not check if the answer is smaller after sharing.', 'The answer 3/2 as a wrong option, with a reason that names the idea.', 'Sharing makes each part smaller: the answer must be less than 3/8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_BY_FRACTION.M_DIVISOR_NOT_INVERTED', 'MATH.G7.NUMBER.FRACTIONS.DIVIDE_BY_FRACTION', 'Multiplies by the divisor without turning it upside down.', '{"question":"3/4 divided by 3/8","wrong_answer":"9/32","correct_answer":"2"}'::jsonb, 'Changes the sign but forgets the flip.', 'The answer 9/32 as a wrong option, with a reason that names the idea.', 'Turn the second fraction over: 3/4 x 8/3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_BY_FRACTION.M_BOTH_FRACTIONS_INVERTED', 'MATH.G7.NUMBER.FRACTIONS.DIVIDE_BY_FRACTION', 'Turns both fractions upside down.', '{"question":"3/4 divided by 3/8","wrong_answer":"32/9","correct_answer":"2"}'::jsonb, 'Overgeneralises the flip.', 'The answer 32/9 as a wrong option, with a reason that names the idea.', 'Only the second fraction turns over. The first stays.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_BY_FRACTION.M_MIXED_NUMBER_NOT_CONVERTED', 'MATH.G7.NUMBER.FRACTIONS.DIVIDE_BY_FRACTION', 'Divides only the whole part of a mixed number and keeps the fraction part.', '{"question":"2 1/2 divided by 1/2","wrong_answer":"4 1/2","correct_answer":"5"}'::jsonb, 'Treats a mixed number as two separate numbers.', 'The answer 4 1/2 as a wrong option, with a reason that names the idea.', 'Write 2 1/2 as 5/2, then 5/2 x 2/1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_WHOLE_BY_FRACTION.M_SMALL_DIVIDED_BY_LARGE', 'MATH.G7.NUMBER.FRACTIONS.DIVIDE_WHOLE_BY_FRACTION', 'Divides the small amount by the large one.', '{"question":"9 kg of flour, bags of 3/5 kg: which calculation?","wrong_answer":"3/5 divided by 9","correct_answer":"9 divided by 3/5"}'::jsonb, 'Puts the numbers in the order they are written.', 'The answer 3/5 divided by 9 as a wrong option, with a reason that names the idea.', 'Ask: how many bags fit into 9 kg? The 9 is the amount being shared out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_WHOLE_BY_FRACTION.M_TAKEN_AWAY_ONCE', 'MATH.G7.NUMBER.FRACTIONS.DIVIDE_WHOLE_BY_FRACTION', 'Subtracts the fraction once instead of counting how many fit.', '{"question":"9 kg of flour, bags of 3/5 kg: which calculation?","wrong_answer":"9 - 3/5","correct_answer":"9 divided by 3/5"}'::jsonb, 'Does not see division as repeated subtraction.', 'The answer 9 - 3/5 as a wrong option, with a reason that names the idea.', 'Take 3/5 away again and again: how many times can you do it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_WHOLE_BY_FRACTION.M_FRACTION_OF_NOT_HOW_MANY', 'MATH.G7.NUMBER.FRACTIONS.DIVIDE_WHOLE_BY_FRACTION', 'Multiplies to find a part of the whole when asked how many fit.', '{"question":"9 kg of flour, bags of 3/5 kg: which calculation?","wrong_answer":"9 x 3/5","correct_answer":"9 divided by 3/5"}'::jsonb, 'Mixes finding a fraction of an amount with counting lots.', 'The answer 9 x 3/5 as a wrong option, with a reason that names the idea.', '3/5 of 9 is a part. We want to know how many 3/5s fit into 9.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_WHOLE_BY_FRACTION.M_DIVISION_ALWAYS_SMALLER', 'MATH.G7.NUMBER.FRACTIONS.DIVIDE_WHOLE_BY_FRACTION', 'Believes division always makes the answer smaller.', '{"question":"6 divided by 1/2","wrong_answer":"3","correct_answer":"12"}'::jsonb, 'Has only divided by whole numbers.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'How many halves are in 6? Each whole has 2 halves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_ADD_RULE.M_DENOMINATOR_ALSO_CHANGED', 'MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_ADD_RULE', 'Changes the denominator as well as the numerator.', '{"question":"1/5, 2/5, 3/5, ?","wrong_answer":"4/10","correct_answer":"4/5"}'::jsonb, 'Adds the gap to both the top and the bottom.', 'The answer 4/10 as a wrong option, with a reason that names the idea.', 'Adding 1/5 only adds more fifths: the bottom stays 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_ADD_RULE.M_GAP_NOT_CONSTANT', 'MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_ADD_RULE', 'Treats the gap as changing from term to term.', '{"question":"1, 4/5, 3/5, 2/5, ?","wrong_answer":"3/10","correct_answer":"1/5"}'::jsonb, 'Does not compare each pair of neighbours.', 'The answer 3/10 as a wrong option, with a reason that names the idea.', 'Write all terms with the same denominator and check each gap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_ADD_RULE.M_END_NOT_NEXT', 'MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_ADD_RULE', 'Gives a term further on instead of the next term.', '{"question":"1, 4/5, 3/5, 2/5, ? What comes next?","wrong_answer":"0","correct_answer":"1/5"}'::jsonb, 'Jumps to the end of the pattern.', 'The answer 0 as a wrong option, with a reason that names the idea.', 'The next term is the one straight after the last shown.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_MULTIPLY_RULE.M_MULTIPLY_FOR_SMALLER', 'MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_MULTIPLY_RULE', 'Names multiplying by a whole number as the rule for terms that get smaller.', '{"question":"1, 1/3, 1/9: the rule?","wrong_answer":"Multiply by 3","correct_answer":"Divide by 3"}'::jsonb, 'Does not check the direction of the terms.', 'The answer Multiply by 3 as a wrong option, with a reason that names the idea.', 'Multiplying by 3 makes terms bigger; these get smaller.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_MULTIPLY_RULE.M_WHOLE_SUBTRACTED_FROM_FRACTION', 'MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_MULTIPLY_RULE', 'Names taking away a whole number as the rule.', '{"question":"1, 1/3, 1/9: the rule?","wrong_answer":"Take away 3","correct_answer":"Divide by 3"}'::jsonb, 'Believes smaller terms mean subtraction.', 'The answer Take away 3 as a wrong option, with a reason that names the idea.', 'Take away 3 from 1 would be negative. The terms stay positive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_MULTIPLY_RULE.M_FRACTION_SUBTRACTED_NOT_SCALED', 'MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_MULTIPLY_RULE', 'Names taking away the same fraction as the rule.', '{"question":"1, 1/3, 1/9: the rule?","wrong_answer":"Take away 1/3","correct_answer":"Divide by 3"}'::jsonb, 'Uses the first gap and applies it to every term.', 'The answer Take away 1/3 as a wrong option, with a reason that names the idea.', 'Take 1/3 from 1/3 leaves nothing, but 1/9 is next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_IN_TABLE.M_LAST_ROW_TAKEN_AS_ANSWER', 'MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_IN_TABLE', 'Gives the last time in the table as the time the task is done.', '{"question":"2 hours: 1/5, 4 hours: 2/5, 6 hours: 3/5. When is the tank full?","wrong_answer":"6 hours","correct_answer":"10 hours"}'::jsonb, 'Reads off the table instead of continuing it.', 'The answer 6 hours as a wrong option, with a reason that names the idea.', 'The tank is only 3/5 full at 6 hours. Continue the pattern.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_IN_TABLE.M_STEPS_COUNTED_NOT_HOURS', 'MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_IN_TABLE', 'Counts the steps of the table as hours.', '{"question":"2 hours: 1/5, 4 hours: 2/5, 6 hours: 3/5. When is the tank full?","wrong_answer":"5 hours","correct_answer":"10 hours"}'::jsonb, 'Forgets the table goes up in 2 hours at a time.', 'The answer 5 hours as a wrong option, with a reason that names the idea.', 'Each row is 2 hours. 5 rows is 10 hours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_IN_TABLE.M_STEP_RATE_AS_HOURLY', 'MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_IN_TABLE', 'Treats the time for one step as the time for the whole task.', '{"question":"2 hours: 1/5, 4 hours: 2/5. When is the tank full?","wrong_answer":"20 hours","correct_answer":"10 hours"}'::jsonb, 'Multiplies the number of steps by the wrong amount of time.', 'The answer 20 hours as a wrong option, with a reason that names the idea.', 'Part filled in one hour first, then how many hours to fill the rest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_CREATE.M_ADDS_TO_NUMERATOR_AND_DENOMINATOR', 'MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_CREATE', 'Adds the rule fraction to both the numerator and the denominator when making terms.', '{"question":"Rule: start at 1/4, add 1/4. Write three terms.","wrong_answer":"1/4, 2/8, 3/12","correct_answer":"1/4, 2/4, 3/4"}'::jsonb, 'Applies the add across idea to a sequence.', 'The answer 1/4, 2/8, 3/12 as a wrong option, with a reason that names the idea.', 'Adding 1/4 adds one more quarter: 2/4, then 3/4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_CREATE.M_GAP_DRIFTS', 'MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_CREATE', 'Writes terms that do not all follow the rule.', '{"question":"Rule: start at 1/2, add 1/4. Write four terms.","wrong_answer":"1/2, 3/4, 1, 1 1/2","correct_answer":"1/2, 3/4, 1, 1 1/4"}'::jsonb, 'Loses the rule partway through.', 'The answer 1/2, 3/4, 1, 1 1/2 as a wrong option, with a reason that names the idea.', 'Check each pair of neighbours against the rule.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DEC_PLACE_AND_TOTAL_VALUE.M_DIGITS_READ_TOP_DOWN', 'MATH.G7.NUMBER.DECIMALS.DEC_PLACE_AND_TOTAL_VALUE', 'Reads the digits of a place value table from the top of the table down instead of by place.', '{"question":"A table lists: tenths 7, ones 1, tens 3, hundredths 4. Write the number.","wrong_answer":"7.134","correct_answer":"31.74"}'::jsonb, 'Ignores the place names on each row.', 'The answer 7.134 as a wrong option, with a reason that names the idea.', 'Sort the rows into place order before you write the number.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DEC_PLACE_AND_TOTAL_VALUE.M_TENS_AND_ONES_SWAPPED', 'MATH.G7.NUMBER.DECIMALS.DEC_PLACE_AND_TOTAL_VALUE', 'Swaps the tens and the ones when writing a number from a table.', '{"question":"Write: tens 4, ones 1, tenths 3, hundredths 7, thousandths 7","wrong_answer":"14.377","correct_answer":"41.377"}'::jsonb, 'Writes the digits in the order they appear in the table.', 'The answer 14.377 as a wrong option, with a reason that names the idea.', 'Tens come before ones; the point comes after the ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DEC_PLACE_AND_TOTAL_VALUE.M_DECIMAL_PLACES_SWAPPED', 'MATH.G7.NUMBER.DECIMALS.DEC_PLACE_AND_TOTAL_VALUE', 'Swaps tenths and hundredths.', '{"question":"Write: ones 4, tenths 3, hundredths 7","wrong_answer":"4.73","correct_answer":"4.37"}'::jsonb, 'Thinks the second place after the point is tenths.', 'The answer 4.73 as a wrong option, with a reason that names the idea.', 'Tenths come straight after the point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DEC_COUNT_TENTHS.M_SAME_NUMBER_REPEATED', 'MATH.G7.NUMBER.DECIMALS.DEC_COUNT_TENTHS', 'Gives the decimal itself as the number of tenths.', '{"question":"How many tenths are in 7.7?","wrong_answer":"7.7","correct_answer":"77"}'::jsonb, 'Does not see tenths as a count.', 'The answer 7.7 as a wrong option, with a reason that names the idea.', 'Each whole is 10 tenths, so 7 wholes are 70 tenths, plus 7 more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DEC_COUNT_TENTHS.M_TENTHS_HUNDREDTHS_CONFUSED', 'MATH.G7.NUMBER.DECIMALS.DEC_COUNT_TENTHS', 'Counts hundredths when asked for tenths.', '{"question":"How many tenths are in 7.7?","wrong_answer":"770","correct_answer":"77"}'::jsonb, 'Mixes the two place names.', 'The answer 770 as a wrong option, with a reason that names the idea.', 'A whole has 10 tenths but 100 hundredths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DEC_COUNT_TENTHS.M_WHOLES_NOT_COUNTED', 'MATH.G7.NUMBER.DECIMALS.DEC_COUNT_TENTHS', 'Counts only the digits after the point and leaves out the wholes.', '{"question":"How many tenths are in 7.7?","wrong_answer":"7","correct_answer":"77"}'::jsonb, 'Forgets that the whole ones are also tenths.', 'The answer 7 as a wrong option, with a reason that names the idea.', 'Count the wholes as tenths: 7 x 10 = 70.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_WHOLE.M_FRACTION_PART_DROPPED', 'MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_WHOLE', 'Multiplies the whole part only and drops the decimal part.', '{"question":"3.5 kg of beans at sh 170 a kilogram","wrong_answer":"sh 510","correct_answer":"sh 595"}'::jsonb, 'Forgets that half a kilogram also costs money.', 'The answer sh 510 as a wrong option, with a reason that names the idea.', 'Find the price of the 0.5 kg and add it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_WHOLE.M_ADDED_NOT_MULTIPLIED', 'MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_WHOLE', 'Adds where the price is for each unit.', '{"question":"3.5 kg at sh 170 for each kilogram","wrong_answer":"173.5","correct_answer":"595"}'::jsonb, 'Sees two numbers and adds.', 'The answer 173.5 as a wrong option, with a reason that names the idea.', 'The price is for each kilogram, so 3.5 kilograms cost 3.5 times as much.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_WHOLE.M_POINT_NOT_MOVED_BACK', 'MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_WHOLE', 'Puts the decimal point in the wrong place after multiplying without it.', '{"question":"3.5 x 170","wrong_answer":"5950","correct_answer":"595"}'::jsonb, 'Forgets to give the answer the number of decimal places of the factors.', 'The answer 5950 as a wrong option, with a reason that names the idea.', 'There is one decimal place in 3.5, so the answer has one place in 5950: 595.0.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_WHOLE.M_DIVIDED_NOT_MULTIPLIED', 'MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_WHOLE', 'Divides where the amount is repeated.', '{"question":"10 tiles of 0.25 m in a row: how long?","wrong_answer":"40","correct_answer":"2.5"}'::jsonb, 'Mixes up how many fit with how long altogether.', 'The answer 40 as a wrong option, with a reason that names the idea.', 'You know the number of tiles and the width of each: multiply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_DEC.M_POINT_FROM_ONE_FACTOR_ONLY', 'MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_DEC', 'Counts the decimal places of one factor only.', '{"question":"0.6 x 0.4","wrong_answer":"2.4","correct_answer":"0.24"}'::jsonb, 'Counts the places of the last number.', 'The answer 2.4 as a wrong option, with a reason that names the idea.', 'Count the places in both numbers: 1 + 1 = 2 places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_DEC.M_PRODUCT_MUST_BE_BIGGER', 'MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_DEC', 'Believes a product is always bigger than both factors.', '{"question":"0.5 x 0.5","wrong_answer":"2.5","correct_answer":"0.25"}'::jsonb, 'Has only multiplied by numbers greater than 1.', 'The answer 2.5 as a wrong option, with a reason that names the idea.', 'Half of a half is a quarter, which is smaller than a half.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_DEC.M_WRONG_QUANTITY_MULTIPLIED', 'MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_DEC', 'Multiplies a price by the length instead of the area.', '{"question":"Grass at sh 60 a square metre, garden 3.6 m by 2.5 m","wrong_answer":"sh 216","correct_answer":"sh 540"}'::jsonb, 'Uses a number from the story that is not the one asked for.', 'The answer sh 216 as a wrong option, with a reason that names the idea.', 'The price is for each square metre, so use the area.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_DEC.M_PERIMETER_FOR_AREA', 'MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_DEC', 'Uses the distance round instead of the area.', '{"question":"Area of a garden 3.6 m by 2.5 m","wrong_answer":"12.2 m2","correct_answer":"9 m2"}'::jsonb, 'Mixes the two measures of a rectangle.', 'The answer 12.2 m2 as a wrong option, with a reason that names the idea.', 'Area is length times width. The distance round is for the fence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DIV_DEC_BY_WHOLE.M_MULTIPLIED_NOT_DIVIDED', 'MATH.G7.NUMBER.DECIMALS.DIV_DEC_BY_WHOLE', 'Multiplies where the amount is shared.', '{"question":"12 litres shared into 8 bottles","wrong_answer":"96","correct_answer":"1.5"}'::jsonb, 'Sees two numbers and multiplies.', 'The answer 96 as a wrong option, with a reason that names the idea.', 'Sharing makes each amount smaller, so divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
