INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DIV_DEC_BY_WHOLE.M_POINT_LOST_IN_QUOTIENT', 'MATH.G7.NUMBER.DECIMALS.DIV_DEC_BY_WHOLE', 'Leaves out the point in the quotient.', '{"question":"12 / 8","wrong_answer":"15","correct_answer":"1.5"}'::jsonb, 'Gets the digits right but forgets the remainder becomes a decimal.', 'The answer 15 as a wrong option, with a reason that names the idea.', 'Put a point after the 1 and continue dividing the remainder.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DIV_DEC_BY_WHOLE.M_POINT_PLACED_WRONG', 'MATH.G7.NUMBER.DECIMALS.DIV_DEC_BY_WHOLE', 'Puts the point one place too far in the quotient.', '{"question":"12 / 8","wrong_answer":"0.15","correct_answer":"1.5"}'::jsonb, 'Counts the places wrongly.', 'The answer 0.15 as a wrong option, with a reason that names the idea.', 'Check by multiplying 0.15 x 8: it is only 1.2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
