INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DIV_BY_DECIMAL.M_POINT_MOVED_ONE_NUMBER', 'MATH.G7.NUMBER.DECIMALS.DIV_BY_DECIMAL', 'Moves the point in the divisor only.', '{"question":"7.5 / 0.5","wrong_answer":"1.5","correct_answer":"15"}'::jsonb, 'Moves one point and not the other.', 'The answer 1.5 as a wrong option, with a reason that names the idea.', 'Move both points the same number of places: 75 / 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DIV_BY_DECIMAL.M_REPEATED_SUBTRACTION_ONCE', 'MATH.G7.NUMBER.DECIMALS.DIV_BY_DECIMAL', 'Subtracts the piece once instead of counting how many fit.', '{"question":"A 7.5 m ribbon cut into 0.5 m pieces","wrong_answer":"7","correct_answer":"15"}'::jsonb, 'Does not see division as counting how many fit.', 'The answer 7 as a wrong option, with a reason that names the idea.', 'Take 0.5 away again and again: how many times?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DIV_BY_DECIMAL.M_MULTIPLIED_INSTEAD_OF_COUNTING', 'MATH.G7.NUMBER.DECIMALS.DIV_BY_DECIMAL', 'Multiplies to count how many pieces fit.', '{"question":"A 7.5 m ribbon cut into 0.5 m pieces","wrong_answer":"3.75","correct_answer":"15"}'::jsonb, 'Chooses multiplication because the numbers are decimals.', 'The answer 3.75 as a wrong option, with a reason that names the idea.', 'To find how many fit, divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DEC_DIVISION_SIZE.M_DIVIDING_ALWAYS_BIGGER', 'MATH.G7.NUMBER.DECIMALS.DEC_DIVISION_SIZE', 'Believes dividing always gives a bigger number.', '{"question":"Dividing by 2: bigger or smaller?","wrong_answer":"bigger","correct_answer":"smaller"}'::jsonb, 'Has just learnt that dividing by 0.2 gives more.', 'The answer bigger as a wrong option, with a reason that names the idea.', 'Dividing by a number more than 1 splits into smaller parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
