INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DEC_DIVISION_SIZE.M_POINT_MOVED_WITHOUT_RULE', 'MATH.G7.NUMBER.DECIMALS.DEC_DIVISION_SIZE', 'Moves the point to make the dividend bigger without moving it in the divisor.', '{"question":"6 / 0.2","wrong_answer":"300","correct_answer":"30"}'::jsonb, 'Thinks the point moves on its own.', 'The answer 300 as a wrong option, with a reason that names the idea.', 'Move both points the same way: 60 / 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
