INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FRACTION.M_NUMERATOR_DOUBLED', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FRACTION', 'Doubles the numerator.', '{"question":"Square of 3/4","wrong_answer":"6/4","correct_answer":"9/16"}'::jsonb, 'Reads squared as doubled.', 'The answer 6/4 as a wrong option, with a reason that names the idea.', 'Squared means multiplied by itself.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_DECIMAL.M_POINT_PLACES_NOT_DOUBLED', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_DECIMAL', 'Gives the square the same number of decimal places as the number.', '{"question":"Square of 0.03","wrong_answer":"0.09","correct_answer":"0.0009"}'::jsonb, 'Forgets that the decimal places of both factors are counted.', 'The answer 0.09 as a wrong option, with a reason that names the idea.', '0.03 has 2 places, so 0.03 x 0.03 has 4 places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
