INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_DECIMAL.M_PERIMETER_FOR_AREA_SQ', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_DECIMAL', 'Gives the distance round when the area is asked.', '{"question":"Area of a square with side 1.5 m","wrong_answer":"6 m","correct_answer":"2.25 m2"}'::jsonb, 'Mixes the two measures.', 'The answer 6 m as a wrong option, with a reason that names the idea.', 'The distance round is 4 sides. The area is the side times the side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_DECIMAL.M_ADDED_NOT_SQUARED', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_DECIMAL', 'Adds to the area instead of squaring the new side.', '{"question":"Side 1.5 m doubled: the new area","wrong_answer":"2.25 + 3","correct_answer":"9"}'::jsonb, 'Works out a change to the old area instead of the new side.', 'The answer 2.25 + 3 as a wrong option, with a reason that names the idea.', 'Find the new side first (3 m), then square it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_DECIMAL.M_CUBED_NOT_SQUARED', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_DECIMAL', 'Multiplies the area by 8 when the side doubles.', '{"question":"Side 1.5 m doubled: the new area","wrong_answer":"18","correct_answer":"9"}'::jsonb, 'Confuses doubling a side with doubling every measure of a solid.', 'The answer 18 as a wrong option, with a reason that names the idea.', 'Area has two directions, so doubling the side multiplies the area by 2 x 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_DECIMAL.M_AREA_DOUBLES_WITH_SIDE', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_DECIMAL', 'Believes doubling the side doubles the area.', '{"question":"Area of a square of side 3 m is 9. New side double: area?","wrong_answer":"18","correct_answer":"36"}'::jsonb, 'Assumes area grows in the same way as length.', 'The answer 18 as a wrong option, with a reason that names the idea.', 'Draw the bigger square: it holds 4 of the old squares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
