INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_WHOLE_NUMBER.M_ROOT_OF_SUM_IS_SUM_OF_ROOTS', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_WHOLE_NUMBER', 'Believes the root of a sum is the sum of the roots.', '{"question":"Root of 36 + 64","wrong_answer":"14","correct_answer":"10"}'::jsonb, 'Treats the root sign as spread across a sum.', 'The answer 14 as a wrong option, with a reason that names the idea.', 'Add first: 36 + 64 = 100, and the root of 100 is 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
