INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_BY_ANCHORS.M_ROOT_BOUNDS_ONE_BELOW', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_BY_ANCHORS', 'Places the root one whole number too low.', '{"question":"Between which whole numbers is the root of 98?","wrong_answer":"8 and 9","correct_answer":"9 and 10"}'::jsonb, 'Uses the perfect square below as if it were the root.', 'The answer 8 and 9 as a wrong option, with a reason that names the idea.', 'Test: 9 x 9 = 81 is less than 98, so the root is more than 9.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_BY_ANCHORS.M_ROOT_BOUNDS_ONE_ABOVE', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_BY_ANCHORS', 'Places the root one whole number too high.', '{"question":"Between which whole numbers is the root of 98?","wrong_answer":"10 and 11","correct_answer":"9 and 10"}'::jsonb, 'Counts up from the perfect square above.', 'The answer 10 and 11 as a wrong option, with a reason that names the idea.', 'Test: 10 x 10 = 100 is more than 98, so the root is less than 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RATE_FIXED.M_RATE_AND_FIXED_SWAPPED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RATE_FIXED', 'Swaps the rate and the fixed amount.', '{"question":"Charge is sh 30 for each jerrican plus sh 10 delivery. Expression for n jerricans?","wrong_answer":"10n + 30","correct_answer":"30n + 10"}'::jsonb, 'Reads the numbers in the order they are written.', 'The answer 10n + 30 as a wrong option, with a reason that names the idea.', 'Test n = 2: the table says 70, but 10 x 2 + 30 is only 50.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RATE_FIXED.M_FIXED_CHARGE_MULTIPLIED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RATE_FIXED', 'Multiplies the fixed charge by n as well.', '{"question":"Charge is sh 30 each plus sh 10 delivery","wrong_answer":"40n","correct_answer":"30n + 10"}'::jsonb, 'Combines the two numbers because both are in shillings.', 'The answer 40n as a wrong option, with a reason that names the idea.', 'The delivery fee is paid once, not for each jerrican.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RATE_FIXED.M_FIXED_ADDED_BEFORE_MULTIPLYING', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RATE_FIXED', 'Adds the fixed amount to n first, then multiplies.', '{"question":"Charge is sh 30 each plus sh 10 delivery","wrong_answer":"30(n + 10)","correct_answer":"30n + 10"}'::jsonb, 'Puts a bracket round everything that is added.', 'The answer 30(n + 10) as a wrong option, with a reason that names the idea.', 'Try n = 2: 30 x 12 = 360, but the charge is 70.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RELATIONS.M_YOUNGER_ADDED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RELATIONS', 'Adds where a person is younger.', '{"question":"Barasa is x. His brother is 2 years younger. The brother''s age?","wrong_answer":"x + 2","correct_answer":"x - 2"}'::jsonb, 'Takes "2 years" as always being added.', 'The answer x + 2 as a wrong option, with a reason that names the idea.', 'Younger means a smaller age: take 2 away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RELATIONS.M_PERSON_MISSED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RELATIONS', 'Leaves out one of the people in the total.', '{"question":"Ages: Barasa x, brother x - 2, mother 3x. Total?","wrong_answer":"4x - 2","correct_answer":"5x - 2"}'::jsonb, 'Adds two of the three expressions.', 'The answer 4x - 2 as a wrong option, with a reason that names the idea.', 'Write all three ages in a line and add them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RELATIONS.M_RELATION_APPLIED_TO_ALL', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RELATIONS', 'Applies the "younger" change to every person by using a bracket.', '{"question":"Ages: x, x - 2 and 3x. Total?","wrong_answer":"5(x - 2)","correct_answer":"5x - 2"}'::jsonb, 'Puts a bracket round the whole sum.', 'The answer 5(x - 2) as a wrong option, with a reason that names the idea.', 'Only the brother is 2 years younger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_FROM_STATEMENT.M_MORE_THAN_AS_PRODUCT', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_FROM_STATEMENT', 'Writes "3 more than x" as 3x.', '{"question":"3 more than x","wrong_answer":"3x","correct_answer":"x + 3"}'::jsonb, 'Puts the number and the letter side by side.', 'The answer 3x as a wrong option, with a reason that names the idea.', 'If x is 5, 3 more than 5 is 8, but 3x would be 15.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_FROM_STATEMENT.M_LESS_THAN_REVERSED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_FROM_STATEMENT', 'Writes "5 less than n" as 5 - n.', '{"question":"5 less than n","wrong_answer":"5 - n","correct_answer":"n - 5"}'::jsonb, 'Writes the numbers in the order they are spoken.', 'The answer 5 - n as a wrong option, with a reason that names the idea.', 'If n is 8, 5 less than 8 is 3: that is 8 - 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS.M_TERM_MISSED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS', 'Leaves one x term out when collecting.', '{"question":"(x + 6) + (4x + 1) + (2x - 1): the number in front of x","wrong_answer":"5","correct_answer":"7"}'::jsonb, 'Adds two of the three terms.', 'The answer 5 as a wrong option, with a reason that names the idea.', 'Underline every x term first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS.M_LIKE_TERMS_MULTIPLIED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS', 'Multiplies the numbers in front of x instead of adding them.', '{"question":"x + 4x + 2x: the number in front of x","wrong_answer":"8","correct_answer":"7"}'::jsonb, 'Thinks collecting means multiplying.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'x + 4x + 2x is 1 + 4 + 2 = 7 lots of x.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS.M_COEFFICIENT_ONE_ASSUMED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS', 'Counts each x term as one x whatever the number in front.', '{"question":"x + 4x + 2x: the number in front of x","wrong_answer":"3","correct_answer":"7"}'::jsonb, 'Counts the terms, not the amounts.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'Add the numbers in front: 4x means four x.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS.M_SIGN_DROPPED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS', 'Ignores the minus sign of a number term.', '{"question":"Number terms +6, +1 and -1: the total","wrong_answer":"8","correct_answer":"6"}'::jsonb, 'Adds the digits and forgets the sign.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'The last term takes 1 away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS.M_CONSTANT_TERM_MISSED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS', 'Leaves a number term out when adding the numbers.', '{"question":"Number terms +6, +1 and -1: the total","wrong_answer":"7","correct_answer":"6"}'::jsonb, 'Adds two of the three numbers.', 'The answer 7 as a wrong option, with a reason that names the idea.', 'List all the plain numbers before adding.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS.M_CONSTANTS_MULTIPLIED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS', 'Multiplies the plain numbers instead of adding.', '{"question":"Number terms +6, +1 and -1: the total","wrong_answer":"-6","correct_answer":"6"}'::jsonb, 'Applies the rule for x terms wrongly to numbers.', 'The answer -6 as a wrong option, with a reason that names the idea.', 'Like terms are added.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS.M_COEFFICIENT_ADDED_TO_VALUE', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS', 'Adds the number in front of x to the value of x instead of multiplying.', '{"question":"7x + 6 when x = 3","wrong_answer":"16","correct_answer":"27"}'::jsonb, 'Reads 7x as 7 + x.', 'The answer 16 as a wrong option, with a reason that names the idea.', '7x means 7 times x.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS.M_CONSTANT_LEFT_OUT', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS', 'Leaves out the plain number when substituting.', '{"question":"7x + 6 when x = 3","wrong_answer":"21","correct_answer":"27"}'::jsonb, 'Stops after the x term.', 'The answer 21 as a wrong option, with a reason that names the idea.', 'The number term is part of the expression.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS.M_CONSTANT_SIGN_FLIPPED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS', 'Subtracts a number term that is added.', '{"question":"7x + 6 when x = 3","wrong_answer":"15","correct_answer":"27"}'::jsonb, 'Changes the sign of the number.', 'The answer 15 as a wrong option, with a reason that names the idea.', 'Keep the sign it has: plus 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_WITH_BRACKETS.M_BRACKET_FIRST_TERM_ONLY', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_WITH_BRACKETS', 'Multiplies only the first term in the bracket.', '{"question":"2 x (x + 8)","wrong_answer":"2x + 8","correct_answer":"2x + 16"}'::jsonb, 'Forgets the second term is multiplied too.', 'The answer 2x + 8 as a wrong option, with a reason that names the idea.', 'Draw arrows from the 2 to both terms.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_WITH_BRACKETS.M_UNLIKE_TERMS_JOINED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_WITH_BRACKETS', 'Joins an x term with a number term.', '{"question":"2 x (x + 8) written 2 x 9x","wrong_answer":"18x","correct_answer":"2x + 16"}'::jsonb, 'Adds x and 8 to make 9x.', 'The answer 18x as a wrong option, with a reason that names the idea.', 'x and 8 are different kinds of term: they cannot be joined.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.FORM_EQUATION_FROM_STORY.M_BRACKET_ADDED_TO_EVERY_TERM', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.FORM_EQUATION_FROM_STORY', 'Adds the fixed amount to each item with a bracket.', '{"question":"8 books at x each plus a set at sh 150, total sh 398","wrong_answer":"8(x + 150) = 398","correct_answer":"8x + 150 = 398"}'::jsonb, 'Thinks the set is bought with every book.', 'The answer 8(x + 150) = 398 as a wrong option, with a reason that names the idea.', 'The set is bought once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.FORM_EQUATION_FROM_STORY.M_MULTIPLIER_AS_ADDEND', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.FORM_EQUATION_FROM_STORY', 'Writes the number of items as an added number.', '{"question":"8 books at x each plus a set at sh 150, total sh 398","wrong_answer":"x + 8 + 150 = 398","correct_answer":"8x + 150 = 398"}'::jsonb, 'Reads "8 books and x" as adding.', 'The answer x + 8 + 150 = 398 as a wrong option, with a reason that names the idea.', '8 books each costing x is 8 times x.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.FORM_EQUATION_FROM_STORY.M_FIXED_ON_WRONG_SIDE', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.FORM_EQUATION_FROM_STORY', 'Adds the fixed amount to the total instead of taking it from the total.', '{"question":"8 books at x each plus a set at sh 150, total sh 398","wrong_answer":"8x = 398 + 150","correct_answer":"8x + 150 = 398"}'::jsonb, 'Moves a number to the other side without changing its sign.', 'The answer 8x = 398 + 150 as a wrong option, with a reason that names the idea.', 'The set is part of the total, so it stays with the books on the left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_TWO_STEP.M_DIVISION_STEP_MISSED', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_TWO_STEP', 'Stops before dividing by the number in front of x.', '{"question":"6x + 6 = 78","wrong_answer":"72","correct_answer":"12"}'::jsonb, 'Takes the first step and thinks the equation is solved.', 'The answer 72 as a wrong option, with a reason that names the idea.', 'We want x, not 6x: divide by 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_TWO_STEP.M_SIGN_NOT_REVERSED', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_TWO_STEP', 'Adds the number to both sides when it is already added.', '{"question":"6x + 6 = 78","wrong_answer":"14","correct_answer":"12"}'::jsonb, 'Applies the same operation instead of the opposite one.', 'The answer 14 as a wrong option, with a reason that names the idea.', 'To undo + 6, take 6 from both sides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_TWO_STEP.M_INVERSE_OPERATION_WRONG', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_TWO_STEP', 'Multiplies when the step is to divide.', '{"question":"3n = 42","wrong_answer":"126","correct_answer":"14"}'::jsonb, 'Does the same operation instead of the opposite one.', 'The answer 126 as a wrong option, with a reason that names the idea.', 'To undo times 3, divide by 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_TWO_STEP.M_LAST_ROW_TAKEN', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_TWO_STEP', 'Gives the last value in a table as the solution.', '{"question":"Table of 6x + 6 for x = 1, 2, 3: solve 6x + 6 = 78","wrong_answer":"3","correct_answer":"12"}'::jsonb, 'Reads off the table instead of continuing it.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'Continue the pattern until the value is 78.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_BOTH_SIDES.M_UNKNOWN_TERM_MOVED_SAME_SIGN', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_BOTH_SIDES', 'Moves an x term to the other side without changing its sign.', '{"question":"4x - 4 = 2x + 12","wrong_answer":"6x = 16","correct_answer":"2x = 16"}'::jsonb, 'Treats moving as copying.', 'The answer 6x = 16 as a wrong option, with a reason that names the idea.', 'Take 2x from both sides: it goes from the right and leaves the left smaller.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_BOTH_SIDES.M_ONE_SIDE_ONLY_CHANGED', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_BOTH_SIDES', 'Does a step on one side only.', '{"question":"4x - 4 = 2x + 12: take 2x from the left only","wrong_answer":"2x - 4 = 2x + 12","correct_answer":"2x - 4 = 12"}'::jsonb, 'Forgets the balance.', 'The answer 2x - 4 = 2x + 12 as a wrong option, with a reason that names the idea.', 'Do the same to both sides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.EQUATION_BALANCE_REASON.M_NUMBER_SIZE_DECIDES_STEP', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.EQUATION_BALANCE_REASON', 'Says a number is taken off both sides because it is the bigger number.', '{"question":"Why take 8 from both sides in x + 8 = 28?","wrong_answer":"because 8 is the bigger number","correct_answer":"doing the same to both sides keeps them equal"}'::jsonb, 'Looks for a reason in the size of numbers.', 'The answer because 8 is the bigger number as a wrong option, with a reason that names the idea.', 'It is not about size: a balance stays level if you do the same to both sides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.EQUATION_BALANCE_REASON.M_UNKNOWN_ALWAYS_LEFT', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.EQUATION_BALANCE_REASON', 'Believes the unknown must always be on the left.', '{"question":"Why take 8 from both sides?","wrong_answer":"x must stay on the left","correct_answer":"to keep the sides equal"}'::jsonb, 'Has only seen x on the left.', 'The answer x must stay on the left as a wrong option, with a reason that names the idea.', '28 = x + 8 is the same equation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.EQUATION_BALANCE_REASON.M_RULE_WITHOUT_REASON', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.EQUATION_BALANCE_REASON', 'Says it is just the rule, with no reason.', '{"question":"Why take 8 from both sides?","wrong_answer":"it is just the rule","correct_answer":"to keep the sides equal"}'::jsonb, 'Has memorised the steps without a picture.', 'The answer it is just the rule as a wrong option, with a reason that names the idea.', 'Use a balance with bags of sweets.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_IN_CONTEXT.M_FIXED_PART_IGNORED', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_IN_CONTEXT', 'Divides the whole charge by the rate and ignores the fixed part.', '{"question":"Parking sh 20 for each hour plus sh 30 fixed, total sh 210: hours?","wrong_answer":"10.5","correct_answer":"9"}'::jsonb, 'Forgets the fixed charge is in the total.', 'The answer 10.5 as a wrong option, with a reason that names the idea.', 'Take the fixed part away before dividing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_IN_CONTEXT.M_ASKED_QUANTITY_MIXED', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_IN_CONTEXT', 'Gives the unknown instead of the quantity asked.', '{"question":"Mother is 4 times Makena. In 4 years the sum of their ages is 63. Mother''s age now?","wrong_answer":"11 (Makena)","correct_answer":"44"}'::jsonb, 'Answers with the letter value.', 'The answer 11 (Makena) as a wrong option, with a reason that names the idea.', 'Read the last line of the question again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
